{"content": "1|//! Pure projection of manifest-pinned contracts and committed public SHM state.
2|//!
3|//! This module performs no I/O. State must already have passed both the private
4|//! state boundary and the sealed schema's public-state policy. Even then, only
5|//! explicitly selected infrastructure fields are retained here.
6|use op_cozo_store::{
7|    GraphAssertion, GraphEdge, GraphEvidence, GraphNode, GraphProvenance, GraphSnapshot,
8|};
9|use op_state_store::PluginSchema;
10|use serde_json::{Value, json};
11|use sha2::{Digest, Sha256};
12|use std::collections::{BTreeMap, BTreeSet};
13|
14|/// The collector owns catalog pinning, snapshot consistency and public filtering.
15|#[derive(Debug, Clone)]
16|pub struct GraphPluginProjection {
17|    pub schema: PluginSchema,
18|    pub schema_hash: String,
19|    pub state: Option<Value>,
20|}
21|
22|const MAX_DOMAIN_RECORDS: usize = 4096;
23|
24|pub fn project_system_graph(
25|    plugins: &BTreeMap<String, GraphPluginProjection>,
26|    mut provenance: GraphProvenance,
27|) -> GraphSnapshot {
28|    let mut graph = Projection::default();
29|    for (plugin, input) in plugins {
30|        let plugin_id = id("plugin", &[plugin]);
31|        graph.node(&plugin_id, "plugin", plugin, json!({
32|            "schema_hash": input.schema_hash,
33|            "schema_version": input.schema.version,
34|            "category": input.schema.category,
35|            "state_coverage": if input.state.is_some() { "public_projection" } else { "unavailable" },
36|            "authority": "sealed_catalog",
37|        }));
38|        if input.state.is_none() {
39|            graph.limit(format!(
40|                "{plugin}: committed public state unavailable; no absence inferred"
41|            ));
42|        }
43|    }
44|    for (plugin, input) in plugins {
45|        let plugin_id = id("plugin", &[plugin]);
46|        let source = format!("sealed:{plugin}:{}", input.schema_hash);
47|        for dependency in &input.schema.dependencies {
48|            if plugins.contains_key(dependency) {
49|                graph.edge(
50|                    &plugin_id,
51|                    "depends_on",
52|                    &id("plugin", &[dependency]),
53|                    declared(&source, "schema.dependencies"),
54|                );
55|            } else {
56|                graph.limit(format!(
57|                    "{plugin}: declared dependency {dependency} unresolved in pinned catalog"
58|                ));
59|            }
60|        }
61|        let methods: BTreeMap<_, _> = input.schema.methods.iter().collect();
62|        for (key, method) in methods {
63|            let method_id = id("method", &[plugin, key]);
64|            graph.node(
65|                &method_id,
66|                "method",
67|                key,
68|                json!({
69|                    "transport_name": method.name,
70|                    "side_effect": method.side_effect,
71|                    "idempotent": method.idempotent,
72|                    "availability": "declared_only",
73|                }),
74|            );
75|            let location = format!("schema.methods.{key}");
76|            graph.edge(
77|                &plugin_id,
78|                "declares_method",
79|                &method_id,
80|                declared(&source, &location),
81|            );
82|            if let Some(capability) = &method.required_capability {
83|                let capability_id = id("capability", &[capability]);
84|                graph.node(
85|                    &capability_id,
86|                    "capability",
87|                    capability,
88|                    json!({"grants": "not_projected"}),
89|                );
90|                graph.edge(
91|                    &method_id,
92|                    "requires_capability",
93|                    &capability_id,
94|                    declared(&source, &format!("{location}.required_capability")),
95|                );
96|            }
97|            if !method.subid.is_empty() {
98|                let subid = id("operational_taxonomy", &[&method.subid]);
99|                graph.node(&subid, "operational_taxonomy", &method.subid, json!({}));
100|                graph.edge(
101|                    &method_id,
102|                    "classified_by",
103|                    &subid,
104|                    declared(&source, &format!("{location}.subid")),
105|                );
106|            }
107|        }
108|        if let Some(state) = input.state.as_ref().filter(|state| state.is_object()) {
109|            let state_source = format!("public_shm:{plugin}:{}", input.schema_hash);
110|            match plugin.as_str() {
111|                "incus" => graph.incus(state, &plugin_id, &state_source, &input.schema),
112|                "btrfs" => graph.btrfs(state, &plugin_id, &state_source),
113|                "qdrant" => graph.qdrant(state, &plugin_id, &state_source),
114|                "mail_server" => graph.mail(state, &plugin_id, &state_source),
115|                "embedding_model" => graph.embedding(state, &plugin_id, &state_source),
116|                "memory" => {
117|                    graph.extend(&plugin_id, select(state, &["backend", "isolation"]));
118|                    graph.limit(
119|                        "memory: private namespaces, entries and content deliberately excluded"
120|                            .into(),
121|                    );
122|                }
123|                "cognitive" => graph.extend(
124|                    &plugin_id,
125|                    select(state, &["bridge_owned", "execution_model"]),
126|                ),
127|                "json_render" => graph.ui(state, &plugin_id, &state_source),
128|                _ => {}
129|            }
130|        }
131|    }
132|    graph.source_declarations(plugins);
133|    graph.resolve_container_references();
134|    provenance.coverage.extend([
135|        "sealed_plugin_methods_capabilities_taxonomy".into(),
136|        "allowlisted_public_infrastructure_state".into(),
137|        "source_declared_subsystems_separate_from_observations".into(),
138|    ]);
139|    provenance.limitations.extend(graph.limitations);
140|    provenance.coverage.sort();
141|    provenance.coverage.dedup();
142|    provenance.limitations.sort();
143|    provenance.limitations.dedup();
144|    // The store bounds receipt metadata independently of node/edge count. A
145|    // large catalog with withheld state must remain readable as an explicitly
146|    // incomplete inventory, rather than fail just because its warnings grow.
147|    if provenance.limitations.len() > 256 {
148|        let omitted = provenance.limitations.len() - 255;
149|        provenance.limitations.truncate(255);
150|        provenance.limitations.push(format!(
151|            "{omitted} additional coverage limitations omitted by the metadata bound; this inventory is incomplete"
152|        ));
153|    }
154|    GraphSnapshot {
155|        format_version: 1,
156|        namespace: "runtime:public".into(),
157|        provenance,
158|        nodes: graph.nodes.into_values().collect(),
159|        edges: graph.edges.into_values().collect(),
160|    }
161|}
162|
163|#[derive(Default)]
164|struct Projection {
165|    nodes: BTreeMap<String, GraphNode>,
166|    edges: BTreeMap<(String, String, String), GraphEdge>,
167|    limitations: BTreeSet<String>,
168|    container_references: Vec<(String, String, GraphEvidence)>,
169|}
170|
171|impl Projection {
172|    fn limit(&mut self, limitation: String) {
173|        self.limitations.insert(limitation);
174|    }
175|
176|    fn node(&mut self, id: &str, kind: &str, label: &str, attributes: Value) {
177|        self.nodes.entry(id.into()).or_insert_with(|| GraphNode {
178|            id: id.into(),
179|            kind: kind.into(),
180|            label: label.into(),
181|            attributes: object(attributes),
182|        });
183|    }
184|
185|    fn extend(&mut self, id: &str, attributes: BTreeMap<String, Value>) {
186|        if let Some(node) = self.nodes.get_mut(id) {
187|            node.attributes.extend(attributes);
188|        }
189|    }
190|
191|    fn edge(&mut self, src: &str, relation: &str, dst: &str, evidence: GraphEvidence) {
192|        let edge = self
193|            .edges
194|            .entry((src.into(), relation.into(), dst.into()))
195|            .or_insert_with(|| GraphEdge {
196|                src: src.into(),
197|                relation: relation.into(),
198|                dst: dst.into(),
199|                evidence: Vec::new(),
200|                attributes: BTreeMap::new(),
201|            });
202|        if !edge.evidence.iter().any(|existing| {
203|            existing.source == evidence.source && existing.locator == evidence.locator
204|        }) {
205|            edge.evidence.push(evidence);
206|            edge.evidence
207|                .sort_by(|a, b| (&a.source, &a.locator).cmp(&(&b.source, &b.locator)));
208|        }
209|    }
210|
211|    fn resource(
212|        &mut self,
213|        owner: &str,
214|        kind: &str,
215|        name: &str,
216|        attributes: Value,
217|        source: &str,
218|        locator: &str,
219|    ) -> String {
220|        let node = id(kind, &[owner, name]);
221|        self.node(&node, kind, name, attributes);
222|        self.edge(owner, "exposes", &node, observed(source, locator));
223|        node
224|    }
225|
226|    // Select named records deterministically, withholding conflicting duplicates.
227|    fn records<'a>(
228|        &mut self,
229|        value: &'a Value,
230|        key: &str,
231|        source: &str,
232|    ) -> BTreeMap<String, &'a Value> {
233|        let Some(array) = value.as_array() else {
234|            self.limit(format!(
235|                "{source}: inventory field unavailable or malformed"
236|            ));
237|            return BTreeMap::new();
238|        };
239|        if array.len() > MAX_DOMAIN_RECORDS {
240|            self.limit(format!(", "total_lines": 1047, "file_size": 40474, "truncated": true, "hint": "Use offset=241 to continue reading (showing 1-240 of 1047 lines)", "is_binary": false, "is_image": false, "not_found": false}

