187|    pub nodes: Vec<GraphReachedNode>,
188|    pub edges: Vec<GraphEdge>,
189|    pub truncated: bool,
190|    pub truncation_reasons: Vec<String>,
191|}
192|
193|fn error(message: impl Into<String>) -> CozoError {
194|    CozoError::Other(message.into())
195|}
196|fn text(value: &str) -> DataValue {
197|    DataValue::Str(value.into())
198|}
199|fn check_text(value: &str, max: usize, name: &str) -> GraphResult<()> {
200|    if value.is_empty() || value.len() > max || value.chars().any(char::is_control) {
201|        Err(error(format!("invalid system graph {name}")))
202|    } else {
203|        Ok(())
204|    }
205|}
206|fn optional_text(value: Option<&str>, name: &str) -> GraphResult<()> {
207|    if let Some(value) = value {
208|        check_text(value, 512, name)?;
209|    }
210|    Ok(())
211|}
212|fn encode(value: &impl Serialize) -> GraphResult<String> {
213|    Ok(serde_json::to_string(value)?)
214|}
215|fn run(tx: &MultiTransaction, script: &str, params: Params) -> GraphResult<NamedRows> {
216|    tx.run_script(script, params)
217|        .map_err(|e| error(format!("system graph: {e}")))
218|}
219|fn cell(row: &[DataValue], index: usize) -> GraphResult<&str> {
220|    row.get(index)
221|        .and_then(dv_as_str)
222|        .ok_or_else(|| error("system graph row has incompatible columns"))
223|}
224|fn canonical(snapshot: &GraphSnapshot) -> GraphResult<GraphSnapshot> {
225|    if snapshot.format_version != SYSTEM_GRAPH_FORMAT_VERSION {
226|        return Err(error("unsupported system graph format"));
227|    }
228|    check_text(&snapshot.namespace, 512, "namespace")?;
229|    if snapshot.nodes.len() > MAX_SYSTEM_GRAPH_NODES
230|        || snapshot.edges.len() > MAX_SYSTEM_GRAPH_EDGES
231|    {
232|        return Err(error("system graph snapshot cardinality exceeds bounds"));
233|    }
234|    let provenance = &snapshot.provenance;
235|    check_text(&provenance.source_commit, 512, "source commit")?;
236|    optional_text(provenance.release_id.as_deref(), "release id")?;
237|    if provenance.kind == GraphProvenanceKind::PreparedRelease && provenance.release_id.is_none() {
238|        return Err(error("prepared release graph requires a release id"));
239|    }
240|    chrono::DateTime::parse_from_rfc3339(&provenance.generated_at)", "total_lines": 787, "file_size": 32115, "truncated": true, "hint": "Use offset=241 to continue reading (showing 1-240 of 787 lines)", "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|//! A system inventory is derived from committed public SHM, never method
2|//! arguments, an event payload, private memory or an independent host scan.
3|
4|use std::collections::BTreeMap;
