33|pub(crate) fn committed_system_graph(catalog_dir: &Path, state_dir: &str) -> Result<GraphSnapshot> {
34|    let before = crate::sealed_schema_reader::manifest_plugins(catalog_dir)?;
35|    ensure!(
36|        before.len() <= MAX_CATALOG_PLUGINS,
37|        "system graph catalog exceeds plugin limit"
38|    );
39|    let catalog = crate::sealed_schema_reader::read_manifest_pinned_catalog(catalog_dir)?;
40|    let selected: Vec<String> = STATE_PLUGINS
41|        .iter()
42|        .filter(|id| catalog.plugins.contains_key(**id))
43|        .map(|id| (*id).to_owned())
44|        .collect();
45|    let mut snapshot = op_core::projection_shm::read_projection_snapshot_bounded_in(
46|        state_dir,
47|        &selected,
48|        MAX_STATE_BYTES,
49|    )?;
50|    let mut plugins = BTreeMap::new();
51|    for (id, document) in catalog.plugins {
52|        let state = snapshot
53|            .states
54|            .remove(&id)
55|            .map(|mut bytes| -> Result<_> {
56|                let value = simd_json::to_owned_value(&mut bytes)?;
57|                document
58|                    .schema
59|                    .validate_exact_schema_fields(&value)
60|                    .with_context(|| format!("invalid committed {id} projection"))?;
61|                document
62|                    .schema
63|                    .project_public_state(&crate::mutation_engine::public_plugin_value(
64|                        &id, &value,
65|                    ))?
66|                    .map(serde_json::to_value)
67|                    .transpose()
68|                    .map_err(Into::into)
69|            })
70|            .transpose()?
71|            .flatten();
72|        plugins.insert(
73|            id,
74|            GraphPluginProjection {
75|                schema: document.schema,
76|                schema_hash: document.schema_hash,
77|                state,
78|            },
79|        );
80|    }
81|    ensure!(
82|        crate::sealed_schema_reader::manifest_plugins(catalog_dir)? == before,
83|        "sealed catalog changed during graph observation; retry"
84|    );
85|    let provenance = GraphProvenance {
86|        kind: GraphProvenanceKind::ObservedRuntime,
87|        source_commit: "unknown".into(),
88|        release_id: None,
89|        generated_at: chrono::Utc::now().to_rfc3339(),
90|        inputs: BTreeMap::from([
91|            ("sealed_catalog_sha256".into(), catalog.catalog_hash),
92|            ("shm_generation".into(), snapshot.generation.to_string()),
93|        ]),
94|        coverage: vec!["manifest-pinned plugin contracts".into(), "committed public subsystem state".into()],
95|        limitations: vec![
96|            "Capture time is not backend observation time; absent public state is unknown, not absent infrastructure.".into(),
97|            "This snapshot does not independently probe services or identify the active release; compare the prepared-release inventory separately.".into(),
98|            "Private memory, conversations, credentials and mail content are excluded.".into(),
99|        ],
100|    };
101|    Ok(project_system_graph(&plugins, provenance))
