{"content": "1|//! Offline verification/import of a typed, namespace-owned system graph.
2|//! Never point this example at a live service's database. Live imports use
3|//! cozo.replace_system_graph through authenticated D-Bus/3tchedFS.
4|//!
5|//! Convert the source export with system_graph_inventory --source-graph first.
6|//! Usage: load_crate_graph SNAPSHOT.json [OFFLINE_ROCKSDB_DIR EXPECTED_REVISION]
7|//! Persistent replacement requires an explicit revision and cannot silently
8|//! retain stale edges or clear another graph owner's rows.
9|
10|use std::{io::Read, path::PathBuf};
11|
12|use op_cozo_store::{CozoGraphShuttle, GraphSnapshot, MAX_SYSTEM_GRAPH_BYTES};
13|
14|fn main() -> Result<(), Box<dyn std::error::Error>> {
15|    let args: Vec<_> = std::env::args().skip(1).collect();
16|    if !matches!(args.len(), 1 | 3) {
17|        return Err(
18|            "usage: load_crate_graph SNAPSHOT.json [OFFLINE_ROCKSDB_DIR EXPECTED_REVISION]".into(),
19|        );
20|    }
21|    let mut bytes = Vec::new();
22|    std::fs::File::open(&args[0])?
23|        .take(MAX_SYSTEM_GRAPH_BYTES as u64 + 1)
24|        .read_to_end(&mut bytes)?;
25|    if bytes.len() > MAX_SYSTEM_GRAPH_BYTES {
26|        return Err("system graph snapshot exceeds byte limit".into());
27|    }
28|    let snapshot: GraphSnapshot = serde_json::from_slice(&bytes)?;
29|    let (store, expected) = if args.len() == 3 {
30|        (
31|            CozoGraphShuttle::new_persistent(PathBuf::from(&args[1]))?,
32|            args[2].parse()?,
33|        )
34|    } else {
35|        (CozoGraphShuttle::new_in_memory()?, 0)
36|    };
37|    let receipt = store.replace_system_graph(&snapshot, expected)?;
38|    println!("{}", serde_json::to_string_pretty(&receipt)?);
39|    Ok(())
