125|fn attrs(value: Value) -> BTreeMap<String, Value> {
126|    value
127|        .as_object()
128|        .expect("attributes object")
129|        .iter()
130|        .map(|(k, v)| (k.clone(), v.clone()))
131|        .collect()
132|}
133|fn evidence(
134|    source: &str,
135|    locator: impl Into<String>,
136|    assertion: GraphAssertion,
137|) -> Vec<GraphEvidence> {
138|    vec![GraphEvidence {
139|        source: source.into(),
140|        locator: locator.into(),
141|        assertion,
142|    }]
143|}
144|fn edge(
145|    src: impl Into<String>,
146|    relation: &str,
147|    dst: impl Into<String>,
148|    source: &str,
149|    locator: impl Into<String>,
150|    attributes: Value,
151|) -> GraphEdge {
152|    GraphEdge {
153|        src: src.into(),
154|        relation: relation.into(),
155|        dst: dst.into(),
156|        evidence: evidence(source, locator, GraphAssertion::Declared),
157|        attributes: attrs(attributes),
158|    }
159|}
160|fn digest(bytes: &[u8]) -> String {
161|    format!("{:x}", Sha256::digest(bytes))
162|}
163|fn safe_rel(path: &Path) -> Result<String> {
164|    ensure!(
165|        path.components().all(|c| matches!(c, Component::Normal(_))),
166|        "non-relative path"
167|    );
168|    let s = path.to_str().context("non-UTF8 prepared path")?;
169|    ensure!(
170|        s.len() <= 450 && !s.chars().any(char::is_control),
171|        "unsupported prepared path"
172|    );
173|    Ok(s.into())
174|}
175|fn sensitive(path: &str) -> bool {
176|    path.split('/')
177|        .any(|s| matches!(s, "secrets" | "credentials" | "private"))
178|        || path.ends_with(".key")
179|        || path.ends_with(".env")
180|        || path.ends_with("/environment")
181|}
182|fn category(path: &str) -> &'static str {
