906|        Regex::new(r"^\s*use\s+([\w::{}, ]+);").expect("static regex pattern is valid")
907|    });
908|
909|    let mut symbols = Vec::new();
910|    let mut doc_comments = Vec::new();
911|    let mut imports = Vec::new();
912|    let mut pending_doc: Vec<String> = Vec::new();
913|
914|    for line in lines {
915|        let trimmed = line.trim();
916|
917|        if trimmed.starts_with("///") || trimmed.starts_with("//!") {
918|            let doc = trimmed.trim_start_matches('/').trim().to_string();
919|            if !doc.is_empty() {
920|                pending_doc.push(doc);
921|            }
922|            continue;
923|        }
924|
