926|            let kind = caps.get(1).map(|m| m.as_str()).unwrap_or("");
927|            let name = caps.get(2).map(|m| m.as_str()).unwrap_or("");
928|            symbols.push(format!("{kind} {name}"));
929|            if !pending_doc.is_empty() {
930|                doc_comments.push(pending_doc.join(" "));
931|                pending_doc.clear();
932|            }
933|            continue;
934|        }
935|
936|        if let Some(caps) = re_use.captures(trimmed) {
937|            let import = caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string();
938|            // Only keep top-level crate (first segment)
