{"content": "1|import type { DoorClient } from "../grpc/door";
2|import type { RouteSelection } from "./chat-adapter";
3|import type { CatalogModel } from "./model-catalog";
4|import type { Elevate } from "./elevation";
5|import { assertInferenceEndpoint, inferenceEndpointMatches, nativeProfilePath, readDedicatedRoute, readRouterValue, validateDedicatedRoute, verifiedNativeUri } from "./native-routing";
6|
7|const TCHED_ROUTER = "tched_router";
8|const WRITE = "cap.software.tched-router.router.write@v1";
9|export const CONTROL_PLANE_PROVIDER_PATH = "agents.control_plane.model_provider";
10|
11|export type ControlPlaneModelAccess = "self" | "admin";
12|
13|/** The server checks canonical identity, current $ROOT, mode and exact grant.
14| * Selected UI mode and local transport flags are never identity evidence. */
15|export async function controlPlaneModelAccess(client: DoorClient): Promise<ControlPlaneModelAccess> {
16|  const { result } = await client.call<{ can_apply?: unknown }>(
17|    TCHED_ROUTER, "get_own_agent_route_access", {}, "cap.software.tched-router.router.read@v1",
18|  );
19|  if (typeof result.can_apply !== "boolean") throw new Error("The door returned invalid own-model access. Refresh before applying.");
20|  return result.can_apply ? "self" : "admin";
21|}
22|
23|export class ControlPlaneMutationUnconfirmedError extends Error {
24|  constructor(cause: unknown) {
25|    super(`The model change could not be confirmed: ${cause instanceof Error ? cause.message : "door response unavailable"}. Refresh before retrying.`);
26|    this.name = "ControlPlaneMutationUnconfirmedError";
27|  }
28|}
29|
30|/** Read the actual dedicated agent route, then resolve it to a provider key. */
31|export async function currentControlPlaneModel(client: DoorClient, models: CatalogModel[], own?: boolean): Promise<RouteSelection> {
32|  const { reference, modelId, uri } = await readDedicatedRoute(client, "control_plane", own);
33|  const matches = models.filter((model) => model.available && model.model_id === modelId && model.control_plane_profile === reference && inferenceEndpointMatches(uri, model.inference_url_prefix));
34|  // Unmapped native selections remain visible as observed, never guessed.
35|  return { providerId: matches.length === 1 ? matches[0].provider_id : reference, modelId };
36|}
37|
38|/**
39| * Every mode uses the same provider-keyed Cozo catalog. The configured chatbot
40| * uses its bounded own-model operation without elevation; other identities keep
41| * the protected administration path. New methods require a matching reseal.
42| */
43|export async function setControlPlaneModel(
44|  client: DoorClient,
45|  selection: RouteSelection,
46|  models: CatalogModel[],
47|  elevate: Elevate,
48|): Promise<void> {
49|  const model = models.find((row) => row.provider_id === selection.providerId && row.model_id === selection.modelId);
50|  if (!model) throw new Error("That provider/model is no longer in the catalog. Refresh models.");
51|  if (!model.available) throw new Error("That catalog model is unavailable. Refresh models and choose an available model.");
52|  const reference = model.control_plane_profile;
53|  if (!reference) {
54|    throw new Error(`The catalog has no native routing binding for ${selection.providerId} / ${selection.modelId}.`);
55|  }
56|  const path = nativeProfilePath(reference, "model");
57|  const access = await controlPlaneModelAccess(client);
58|  if (access === "self") {
59|    try {
60|      const { result } = await client.call<{
61|        mode?: unknown; reference?: unknown; model?: unknown; uri?: unknown;
62|      }>(
63|        TCHED_ROUTER, "apply_own_agent_route",
64|        { provider_id: selection.providerId, model_id: selection.modelId },
65|        "cap.software.tched-router.agent.route.self.write@v1",
66|      );
67|      const applied = validateDedicatedRoute(result, "control_plane");
68|      if (applied.reference !== reference || applied.modelId !== selection.modelId) {
69|        throw new Error("The applied Control Plane route differs from the selected catalog model.");
70|      }
71|      assertInferenceEndpoint(applied.uri, model.inference_url_prefix);
72|      return;
73|    } catch (cause) {
74|      // No administrative fallback: a denial or lost response cannot turn the
75|      // scoped request into an unrelated broad configuration mutation.
76|      throw new ControlPlaneMutationUnconfirmedError(cause);
77|    }
78|  }
79|  const [currentReference, currentModel, uri] = await Promise.all([
80|    readRouterValue(client, CONTROL_PLANE_PROVIDER_PATH),
81|    readRouterValue(client, path),
82|    verifiedNativeUri(client, reference, model.inference_url_prefix),
83|  ]);
84|  if (currentReference === reference && currentModel === selection.modelId) return;
85|  const providerPointer = "/agents/control_plane/model_provider";
86|  const modelPointer = `/${path.replaceAll(".", "/")}`;
87|  const args = { operations: [
88|    { op: "test", path: providerPointer, value: currentReference },
89|    { op: "test", path: modelPointer, value: currentModel },
90|    { op: "test", path: `/${nativeProfilePath(reference, "uri").replaceAll(".", "/")}`, value: uri },
91|    { op: "replace", path: modelPointer, value: selection.modelId },
92|    { op: "replace", path: providerPointer, value: reference },
93|  ] };
94|  await elevate(TCHED_ROUTER, "config_patch", args);
95|  try {
96|    await client.call(TCHED_ROUTER, "config_patch", args, WRITE);
97|  } catch (cause) {
98|    // A lost response may follow an accepted write. Reconcile before retry;
99|    // preflight and elevation failures never reach this branch.
100|    throw new ControlPlaneMutationUnconfirmedError(cause);
101|  }
102|}
103|
104|/** One-time sudo ticket for an exact protected call (elevation plugin). */
105|export async function authorizeTask(
106|  client: DoorClient,
107|  plugin: string,
108|  method: string,
109|  args: Record<string, unknown>,
110|  password=*** Promise<void> {
112|  await client.call("elevation", "authorize_task", { plugin, method, args, password }, "elevation.authorize");
