1808|fn source_graph(path: &Path, namespace: &str, generated_at: &str) -> Result<GraphSnapshot> {
1809|    let metadata = fs::symlink_metadata(path)?;
1810|    ensure!(
1811|        metadata.is_file() && metadata.len() <= MAX_JSON as u64,
1812|        "source graph requires bounded regular file"
1813|    );
1814|    let mut file = OpenOptions::new()
1815|        .read(true)
1816|        .custom_flags(nix::libc::O_NOFOLLOW)
1817|        .open(path)?;
1818|    let mut bytes = Vec::new();
1819|    Read::by_ref(&mut file)
1820|        .take(MAX_JSON as u64 + 1)
1821|        .read_to_end(&mut bytes)?;
1822|    ensure!(bytes.len() <= MAX_JSON, "source graph exceeds bound");
1823|    let input: LegacyGraph = serde_json::from_slice(&bytes)?;
1824|    ensure!(
1825|        input.nodes.len() <= MAX_ENTRIES && input.edges.len() <= 180_000,
1826|        "source graph entry bound exceeded"
1827|    );
1828|    let mut nodes: BTreeMap<String, GraphNode> = BTreeMap::new();
1829|    let mut commit = None;
1830|    let mut worktree_dirty = None;
1831|    for node in input.nodes {
1832|        ensure!(
1833|            node.id.len() <= 450 && node.props.is_object(),
1834|            "invalid source node"
1835|        );
1836|        if node.id == "meta:crate-graph" {
1837|            commit = node
1838|                .props
1839|                .get("commit")
1840|                .and_then(Value::as_str)
1841|                .map(str::to_owned);
1842|            if let Some(value) = node.props.get("worktree_dirty") {
1843|                worktree_dirty = Some(
1844|                    value
1845|                        .as_bool()
1846|                        .context("source worktree_dirty must be boolean")?,
1847|                );
1848|            }
1849|        }
1850|        let attributes = attrs(node.props.clone());
1851|        if let Some(existing) = nodes.get_mut(&node.id) {
1852|            if existing.kind == node.label && existing.attributes == attributes {
1853|                continue;
1854|            }
1855|            ensure!(
1856|                node.id.starts_with("ext:")
1857|                    && existing.kind == "ext_crate"
1858|                    && node.label == "ext_crate",
1859|                "conflicting duplicate source node {}",
1860|                node.id
1861|            );
1862|            let original = existing.attributes.remove("req");
1863|            let values = existing
1864|                .attributes
1865|                .entry("requirements".into())
1866|                .or_insert_with(|| json!([]))
1867|                .as_array_mut()
1868|                .context("invalid merged requirements")?;
1869|            if let Some(v) = original {
1870|                values.push(v);
1871|            }
1872|            let req = node
1873|                .props
1874|                .get("req")
1875|                .context("external duplicate lacks req")?
1876|                .clone();
1877|            if !values.contains(&req) {
1878|                values.push(req);
1879|            }
1880|            values.sort_by_key(Value::to_string);
1881|            ensure!(
1882|                node.props.as_object().is_some_and(|o| o.len() == 1),
1883|                "external duplicate has unsupported properties"
1884|            );
1885|        } else {
1886|            nodes.insert(
