29|    pub method: String,
30|}
31|
32|/// A complete, immutable contract authored by this plugin. Its sealed output
33|/// schema includes the exact document; callers cannot construct arbitrary JSON
34|/// as a contract. Dynamic payload definitions remain inside the typed document.
35|#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
36|#[serde(transparent)]
37|pub struct FilesystemContract(serde_json::Value);
38|
39|impl FilesystemContract {
40|    pub fn get() -> Self {
41|        Self(chat_fs_contract::document())
42|    }
43|
